using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CosmicWisdomCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Moonie/CosmicWisdomCustomDescription", order = 0)]
public class CosmicWisdomCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		CosmicWisdomAction cosmicWisdomAction = battleAction as CosmicWisdomAction;
		return Smart.Format(GetRawLocalizedDescription(battleAction), cosmicWisdomAction.PurifyAction.GetActionName(), 1);
	}
}
